import csv, re

people = list(csv.DictReader(open("dataset/people_accounts.csv", encoding="utf-8")))
print("last names with spaces:", [p['last_name'] for p in people if ' ' in p['last_name']][:5])
print("first names with spaces:", sorted({p['first_name'] for p in people if ' ' in p['first_name']}))

lines = open("dataset/genealogy_trees.txt", encoding="utf-8").read().split("\n")
WORD = re.compile(r"[^\W\d_]+", re.UNICODE)
tokens = {}  # row -> list of (word, c0, c1)
allwords = 0
for r, l in enumerate(lines):
    toks = [(m.group(0), m.start(), m.end()) for m in WORD.finditer(l)]
    toks = [t for t in toks if not (r < 5 or r > 110)]  # skip header/footer
    if toks:
        tokens[r] = toks
        allwords += len(toks)
print("total words in grid:", allwords)

def find_seq(row, words):
    """find consecutive token runs on row matching words; return list of (c0,c1)"""
    res = []
    toks = tokens.get(row, [])
    for i in range(len(toks) - len(words) + 1):
        if all(toks[i+j][0] == words[j] for j in range(len(words))):
            res.append((toks[i][1], toks[i+len(words)-1][2]))
    return res

matches = {}  # fullname -> list of (r0, r1, c0, c1)
for p in people:
    fn, ln = p['first_name'].split(), p['last_name'].split()
    name = f"{p['first_name']} {p['last_name']}"
    locs = []
    for r in tokens:
        # single line
        for (c0, c1) in find_seq(r, fn + ln):
            locs.append((r, r, c0, c1))
        # wrapped: fn on row r, ln on row r+1
        for (fc0, fc1) in find_seq(r, fn):
            for (lc0, lc1) in find_seq(r + 1, ln):
                if lc0 < fc1 + 15 and lc1 > fc0 - 15:  # roughly aligned
                    locs.append((r, r + 1, min(fc0, lc0), max(fc1, lc1)))
    if locs:
        matches[name] = locs

multi = {n: l for n, l in matches.items() if len(l) > 1}
print("people matched:", len(matches), "of", len(people))
print("multi-location names:", len(multi))
for n, l in list(multi.items())[:10]:
    print("  ", n, l)
