import json, re, csv

lines = open("/app/dataset/genealogy_trees.txt", encoding="utf-8").read().split("\n")
W = max(len(l) for l in lines)
grid = [l.ljust(W) for l in lines]
H = len(grid)

boxes = {k: tuple(v) for k, v in json.load(open("/tmp/boxes.json")).items()}

VERT = set("|│/\\_x+")
HORIZ = set("-~x+")

def at(r, c):
    if 0 <= r < H and 0 <= c < W: return grid[r][c]
    return " "

def is_horiz_row(r, c, exclude_self=True):
    """count horizontal chars near (r,c) on row r"""
    n = 0
    for cc in range(c-4, c+5):
        if exclude_self and cc == c: continue
        if at(r, cc) in HORIZ: n += 1
    return n

def box_at(r, c, direction):
    """direction=down: stem descending ends at box top; direction=up: ends at box bottom"""
    for name, (r0, r1, c0, c1) in boxes.items():
        if not (c0 - 5 <= c <= c1 + 5): continue
        if direction == "down" and r0 - 3 <= r <= r1: return name
        if direction == "up" and r0 <= r <= r1 + 3: return name
    return None

def follow(r, c, dr, self_name):
    """follow a stem from (r,c) in direction dr (+1 down, -1 up).
    returns ('box', name) or ('conn', r, c) or ('dead', r, c)"""
    steps = 0
    while steps < 40:
        steps += 1
        b = box_at(r, c, "down" if dr > 0 else "up")
        if b and b != self_name:
            return ('box', b)
        # connector row test: current char is on a row with horiz run
        if at(r, c) in HORIZ or is_horiz_row(r, c) >= 3:
            if is_horiz_row(r, c) >= 2:
                return ('conn', r, c)
        # advance
        moved = False
        for rgap in (1, 2, 3):
            for dc in (0, -1, 1, -2, 2):
                ch = at(r + dr * rgap, c + dc)
                if ch in VERT:
                    r, c = r + dr * rgap, c + dc
                    moved = True
                    break
            if moved: break
            # maybe connector row is at r+dr*rgap but junction char degraded
            if is_horiz_row(r + dr * rgap, c, exclude_self=False) >= 3:
                return ('conn', r + dr * rgap, c)
        if not moved:
            return ('dead', r, c)
    return ('dead', r, c)

def stem_start(name, dr):
    """find the stem cell just outside the box in direction dr"""
    r0, r1, c0, c1 = boxes[name]
    rows = range(r1 + 1, r1 + 6) if dr > 0 else range(r0 - 1, r0 - 6, -1)
    for r in rows:
        # skip rows that look like box border: many horiz chars within text span
        span = [at(r, c) for c in range(c0 - 2, c1 + 3)]
        nh = sum(1 for ch in span if ch in HORIZ)
        cands = [c for c in range(c0, c1 + 1) if at(r, c) in VERT and at(r,c) != '+']
        if nh >= 3:
            continue  # border row
        # exclude side-border verticals (at or outside text edges +/-2)
        cands = [c for c in cands if c0 + 1 <= c <= c1 - 1]
        if cands:
            mid = (c0 + c1) / 2
            return r, min(cands, key=lambda c: abs(c - mid))
    return None

def walk_connector(r, jc):
    """walk connector row r from junction jc; return (cols_with_down_stem, cols_with_up_stem)"""
    cols = set()
    for direction in (-1, 1):
        c = jc
        gap = 0
        while 0 <= c < W:
            ch = at(r, c)
            if ch in HORIZ:
                cols.add(c); gap = 0
            elif ch == ' ':
                gap += 1
                if gap > 3: break
            else:
                break
            c += direction
    cols.add(jc)
    down, up = [], []
    for c in sorted(cols):
        for rg in (1, 2):
            if any(at(r + rg, c + dc) in (VERT - {'+','x'}) for dc in (-1, 0, 1)):
                down.append(c); break
        for rg in (1, 2):
            if any(at(r - rg, c + dc) in (VERT - {'+','x'}) for dc in (-1, 0, 1)):
                up.append(c); break
    return down, up

def dedupe_adjacent(cols):
    out = []
    for c in cols:
        if out and c - out[-1] <= 2: continue
        out.append(c)
    return out

def children_of(name):
    ss = stem_start(name, +1)
    if not ss: return []
    res = follow(ss[0], ss[1], +1, name)
    if res[0] == 'box':  # direct connection? unusual
        return [res[1]]
    if res[0] != 'conn': return []
    _, r, jc = res
    down, _ = walk_connector(r, jc)
    kids = []
    for c in dedupe_adjacent(down):
        # find stem cell below
        for rg in (1, 2):
            hit = [(r + rg, c + dc) for dc in (0, -1, 1) if at(r + rg, c + dc) in (VERT - {'+','x'})]
            if hit:
                res2 = follow(hit[0][0], hit[0][1], +1, name)
                if res2[0] == 'box': kids.append(res2[1])
                else: kids.append(('?', res2))
                break
    return kids

def parent_of(name):
    ss = stem_start(name, -1)
    if not ss: return None
    res = follow(ss[0], ss[1], -1, name)
    if res[0] == 'box':
        return res[1]
    if res[0] != 'conn': return ('?', res)
    _, r, jc = res
    _, up = walk_connector(r, jc)
    ups = dedupe_adjacent(up)
    results = []
    for c in ups:
        for rg in (1, 2):
            hit = [(r - rg, c + dc) for dc in (0, -1, 1) if at(r - rg, c + dc) in (VERT - {'+','x'})]
            if hit:
                res2 = follow(hit[0][0], hit[0][1], -1, name)
                results.append(res2)
                break
    bx = [x[1] for x in results if x[0] == 'box']
    if len(bx) == 1: return bx[0]
    return ('?', results)

if __name__ == "__main__":
    # trace the ancestor chain of Dawid Majtyka
    cur = "Dawid Majtyka"
    chain = [cur]
    for _ in range(4):
        p = parent_of(cur)
        print(f"parent of {cur}: {p}")
        if not isinstance(p, str): break
        chain.append(p); cur = p
    print("chain:", chain)
